          "type": "policy",
          "source": "lms/djangoapps/courseware/docs/decisions/0002-permissions-via-django-rules.rst",
          "content": "Convert each caller of `has_access` to use `user.has_perm` instead. Implement the new permission created in 1. by referencing to the previous `has_access` call."
        }
