        {
          "type": "code",
          "file": "lms/djangoapps/support/rest_api/v1/views.py",
          "lines": [30, 45],
          "content": "class CourseTeamManageAPIView(...):\n    permission_classes = (IsAuthenticated,)\n    ...\n"
        },
        {
          "type": "policy",
          "source": "lms/djangoapps/courseware/docs/decisions/0002-permissions-via-django-rules.rst",
